<?php
declare(strict_types=1);require_once __DIR__.'/common.php';$user=qa_require_user();qa_post();$qid=(int)($_POST['question_id']??0);$vote=(int)($_POST['vote']??0);if($qid<1||!in_array($vote,[-1,1],true))exit('Invalid vote.');$pdo=db();$check=$pdo->prepare('SELECT id,vote_value FROM qa_votes WHERE question_id=? AND user_id=?');$check->execute([$qid,(int)$user['id']]);$existing=$check->fetch();if($existing){if((int)$existing['vote_value']===$vote){$pdo->prepare('DELETE FROM qa_votes WHERE id=?')->execute([(int)$existing['id']]);}else{$pdo->prepare('UPDATE qa_votes SET vote_value=? WHERE id=?')->execute([$vote,(int)$existing['id']]);}}else{$pdo->prepare('INSERT INTO qa_votes(question_id,user_id,vote_value) VALUES(?,?,?)')->execute([$qid,(int)$user['id'],$vote]);}qa_redirect('view.php?id='.$qid);
